<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --fg: #171717;
      --accent: #0072F5;
      --accent-hover: #0056b3;
      --muted: #6B7280;
      --border: #E5E7EB;
      --card-bg: #FFFFFF;
      --radius: 0.5rem;
      --font: 'Inter', system-ui, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--fg);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    input { font-family: inherit; }

    /* Header */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--border);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 1.5rem;
      height: 4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }

    .logo {
      font-size: 1.25rem;
      font-weight: 800;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }

    .logo svg { color: var(--accent); }

    .nav-main {
      display: flex;
      align-items: center;
      gap: 0.25rem;
    }

    .nav-item {
      position: relative;
      padding: 0.5rem 0.75rem;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--muted);
      border-radius: var(--radius);
      transition: color 150ms, background 150ms;
    }

    .nav-item:hover, .nav-item.active { color: var(--fg); background: rgba(0,0,0,0.04); }

    .nav-item .chevron { width: 14px; height: 14px; margin-left: 2px; opacity: 0.5; }

    /* Dropdown Menus */
    .dropdown {
      position: absolute;
      top: 100%;
      left: 0;
      min-width: 640px;
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 0.75rem;
      box-shadow: 0 20px 40px rgba(0,0,0,0.08), 0 4px 12px rgba(0,0,0,0.04);
      padding: 1.5rem;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: opacity 200ms, transform 200ms, visibility 200ms;
    }

    .nav-item:hover .dropdown,
    .dropdown-trigger:focus + .dropdown,
    .dropdown-trigger:active + .dropdown { opacity: 1; visibility: visible; transform: translateY(0); }

    .dropdown-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
    }

    .dropdown-section h4 {
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--muted);
      margin-bottom: 0.75rem;
    }

    .dropdown-link {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      padding: 0.5rem;
      margin: -0.5rem;
      border-radius: var(--radius);
      transition: background 150ms;
    }

    .dropdown-link:hover { background: rgba(0,0,0,0.03); }

    .dropdown-icon {
      width: 2rem;
      height: 2rem;
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--bg);
      border-radius: 0.375rem;
      flex-shrink: 0;
    }

    .dropdown-icon i { width: 18px; height: 18px; color: var(--fg); }

    .dropdown-text h5 {
      font-size: 0.875rem;
      font-weight: 600;
      margin-bottom: 0.125rem;
    }

    .dropdown-text p {
      font-size: 0.75rem;
      color: var(--muted);
      line-height: 1.4;
    }

    /* Resources dropdown - 3 columns */
    .resources-dropdown { min-width: 560px; }
    .resources-dropdown .dropdown-grid { grid-template-columns: repeat(3, 1fr); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }

    .btn-ghost {
      padding: 0.5rem 0.875rem;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--fg);
      border-radius: var(--radius);
      transition: background 150ms;
    }

    .btn-ghost:hover { background: rgba(0,0,0,0.04); }

    .btn-primary {
      padding: 0.5rem 1rem;
      font-size: 0.875rem;
      font-weight: 600;
      background: var(--fg);
      color: #fff;
      border-radius: var(--radius);
      transition: background 150ms, transform 100ms;
    }

    .btn-primary:hover { background: #000; }
    .btn-primary:active { transform: scale(0.98); }

    /* Hero Section */
    .hero {
      max-width: 1280px;
      margin: 0 auto;
      padding: 3rem 1.5rem 2rem;
      text-align: center;
    }

    .hero h1 {
      font-size: clamp(2rem, 5vw, 3rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 0.75rem;
    }

    .hero p {
      font-size: 1.125rem;
      color: var(--muted);
      max-width: 600px;
      margin: 0 auto;
    }

    /* Search & Filters */
    .filters-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 1.5rem 2rem;
    }

    .search-bar {
      position: relative;
      max-width: 400px;
      margin: 0 auto 1.5rem;
    }

    .search-bar input {
      width: 100%;
      padding: 0.75rem 1rem 0.75rem 2.75rem;
      font-size: 0.875rem;
      border: 1px solid var(--border);
      border-radius: 9999px;
      background: var(--card-bg);
      transition: border-color 150ms, box-shadow 150ms;
    }

    .search-bar input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.1);
    }

    .search-bar i {
      position: absolute;
      left: 1rem;
      top: 50%;
      transform: translateY(-50%);
      width: 18px;
      height: 18px;
      color: var(--muted);
    }

    .filter-pills {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.5rem;
    }

    .filter-pill {
      padding: 0.5rem 1rem;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--muted);
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 9999px;
      transition: all 150ms;
    }

    .filter-pill:hover {
      border-color: var(--fg);
      color: var(--fg);
    }

    .filter-pill.active {
      background: var(--fg);
      color: #fff;
      border-color: var(--fg);
    }

    /* Featured Articles */
    .featured-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 1.5rem 3rem;
    }

    .section-header {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      margin-bottom: 1.5rem;
    }

    .section-header h2 {
      font-size: 0.875rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--muted);
    }

    .section-header i { width: 18px; height: 18px; }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
    }

    .featured-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 1rem;
      overflow: hidden;
      transition: box-shadow 200ms, transform 200ms;
    }

    .featured-card:hover {
      box-shadow: 0 12px 32px rgba(0,0,0,0.08);
      transform: translateY(-4px);
    }

    .featured-card-image {
      height: 160px;
      background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .featured-card:nth-child(2) .featured-card-image {
      background: linear-gradient(135deg, #0f4c75 0%, #3282b8 100%);
    }

    .featured-card:nth-child(3) .featured-card-image {
      background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 100%);
    }

    .featured-card-image::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .featured-card-image i {
      width: 48px;
      height: 48px;
      color: rgba(255,255,255,0.9);
    }

    .featured-card-body {
      padding: 1.25rem;
    }

    .featured-meta {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 0.75rem;
    }

    .category-tag {
      font-size: 0.6875rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      padding: 0.25rem 0.5rem;
      background: rgba(0,114,245,0.1);
      color: var(--accent);
      border-radius: 0.25rem;
    }

    .featured-meta span {
      font-size: 0.8125rem;
      color: var(--muted);
    }

    .featured-card h3 {
      font-size: 1.125rem;
      font-weight: 700;
      line-height: 1.35;
      margin-bottom: 0.5rem;
    }

    .featured-card p {
      font-size: 0.875rem;
      color: var(--muted);
      line-height: 1.5;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    /* Agentic Stats */
    .agentic-stats {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      margin: 1rem 0;
      padding: 1rem;
      background: rgba(0,114,245,0.04);
      border-radius: 0.75rem;
    }

    .stat-item {
      flex: 1;
      min-width: 120px;
    }

    .stat-value {
      font-size: 1.25rem;
      font-weight: 800;
      color: var(--accent);
    }

    .stat-label {
      font-size: 0.75rem;
      color: var(--muted);
      line-height: 1.4;
    }

    /* Latest News */
    .news-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 1.5rem 3rem;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
    }

    .news-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 0.75rem;
      padding: 1.25rem;
      transition: box-shadow 200ms, transform 200ms;
    }

    .news-card:hover {
      box-shadow: 0 8px 24px rgba(0,0,0,0.06);
      transform: translateY(-2px);
    }

    .news-card .category-tag { margin-bottom: 0.75rem; display: inline-block; }

    .news-card h3 {
      font-size: 1rem;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 0.5rem;
    }

    .news-card p {
      font-size: 0.8125rem;
      color: var(--muted);
      line-height: 1.5;
      margin-bottom: 1rem;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-meta {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.8125rem;
      color: var(--muted);
    }

    .author-avatar {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent) 0%, #6366f1 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.625rem;
      font-weight: 600;
      color: #fff;
    }

    /* No Results */
    .no-results {
      display: none;
      text-align: center;
      padding: 4rem 1rem;
      color: var(--muted);
    }

    .no-results i { width: 48px; height: 48px; margin-bottom: 1rem; opacity: 0.5; }

    .no-results h3 { font-size: 1.125rem; font-weight: 600; color: var(--fg); margin-bottom: 0.5rem; }

    /* Show More */
    .show-more-wrapper {
      text-align: center;
      padding: 2rem 0;
    }

    .btn-show-more {
      padding: 0.75rem 2rem;
      font-size: 0.875rem;
      font-weight: 600;
      background: var(--card-bg);
      color: var(--fg);
      border: 1px solid var(--border);
      border-radius: 9999px;
      transition: all 150ms;
    }

    .btn-show-more:hover {
      background: var(--fg);
      color: #fff;
      border-color: var(--fg);
    }

    /* CTA Banner */
    .cta-banner {
      background: var(--fg);
      color: #fff;
      margin: 0 1.5rem 3rem;
      border-radius: 1rem;
      overflow: hidden;
    }

    .cta-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 3rem 2rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 2rem;
    }

    .cta-content h2 {
      font-size: clamp(1.5rem, 3vw, 2rem);
      font-weight: 800;
      margin-bottom: 0.5rem;
    }

    .cta-content p {
      font-size: 1rem;
      color: rgba(255,255,255,0.7);
      max-width: 500px;
    }

    .cta-actions {
      display: flex;
      gap: 0.75rem;
      flex-shrink: 0;
    }

    .btn-cta-primary {
      padding: 0.75rem 1.5rem;
      font-size: 0.875rem;
      font-weight: 600;
      background: var(--accent);
      color: #fff;
      border-radius: var(--radius);
      transition: background 150ms;
    }

    .btn-cta-primary:hover { background: var(--accent-hover); }

    .btn-cta-secondary {
      padding: 0.75rem 1.5rem;
      font-size: 0.875rem;
      font-weight: 600;
      background: transparent;
      color: #fff;
      border: 1px solid rgba(255,255,255,0.3);
      border-radius: var(--radius);
      transition: border-color 150ms;
    }

    .btn-cta-secondary:hover { border-color: rgba(255,255,255,0.6); }

    /* Footer */
    .footer {
      background: var(--card-bg);
      border-top: 1px solid var(--border);
      padding: 3rem 1.5rem;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 2rem;
      margin-bottom: 3rem;
    }

    .footer-col h4 {
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--muted);
      margin-bottom: 1rem;
    }

    .footer-col ul { list-style: none; }

    .footer-col li { margin-bottom: 0.5rem; }

    .footer-col a {
      font-size: 0.875rem;
      color: var(--fg);
      transition: color 150ms;
    }

    .footer-col a:hover { color: var(--accent); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 2rem;
      border-top: 1px solid var(--border);
      font-size: 0.8125rem;
      color: var(--muted);
    }

    .footer-links {
      display: flex;
      gap: 1.5rem;
    }

    .footer-links a:hover { color: var(--fg); }

    .status-indicator {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22c55e;
      border-radius: 50%;
    }

    /* Mobile Nav Toggle */
    .mobile-nav-toggle { display: none; }

    /* Responsive */
    @media (max-width: 1024px) {
      .dropdown { min-width: 480px; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-main { display: none; }
      .header-actions .btn-ghost { display: none; }
      .mobile-nav-toggle { display: flex; }

      .featured-grid { grid-template-columns: 1fr; }
      .news-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }

      .cta-inner { flex-direction: column; text-align: center; }
      .cta-content p { margin: 0 auto; }
      .footer-bottom { flex-direction: column; gap: 1rem; }
    }

    @media (max-width: 640px) {
      .news-grid { grid-template-columns: 1fr; }
      .hero h1 { font-size: 1.75rem; }
      .hero p { font-size: 1rem; }
    }

    /* Animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .animate-in {
      animation: fadeInUp 400ms ease-out forwards;
    }

    .news-card, .featured-card, .filter-pill {
      opacity: 0;
      animation: fadeInUp 400ms ease-out forwards;
    }

    .news-card:nth-child(1), .featured-card:nth-child(1), .filter-pill:nth-child(1) { animation-delay: 50ms; }
    .news-card:nth-child(2), .featured-card:nth-child(2), .filter-pill:nth-child(2) { animation-delay: 100ms; }
    .news-card:nth-child(3), .featured-card:nth-child(3), .filter-pill:nth-child(3) { animation-delay: 150ms; }
    .news-card:nth-child(4), .filter-pill:nth-child(4) { animation-delay: 200ms; }
    .news-card:nth-child(5), .filter-pill:nth-child(5) { animation-delay: 250ms; }
    .news-card:nth-child(6), .filter-pill:nth-child(6) { animation-delay: 300ms; }
    .news-card:nth-child(7), .filter-pill:nth-child(7) { animation-delay: 350ms; }
    .news-card:nth-child(8), .filter-pill:nth-child(8) { animation-delay: 400ms; }
    .news-card:nth-child(9), .filter-pill:nth-child(9) { animation-delay: 450ms; }
  </style>
</head>
