      { category: 'Engineering', title: 'WebSocket scaling: Lessons learned', excerpt: 'Managing 100k+ concurrent WebSocket connections without breaking a sweat.', author: 'Chris Park', date: 'Mar 10', initials: 'CP' },
      { category: 'Customers', title: 'How TechCorp scaled to 10M users', excerpt: 'A case study of infrastructure evolution during hypergrowth.', author: 'Taylor Reed', date: 'Mar 8', initials: 'TR' }
    ];

    let loadedCount = 0;
    const newsGrid = document.getElementById('newsGrid');
    const showMoreBtn = document.getElementById('showMoreBtn');
    const noResults = document.getElementById('noResults');
    const searchInput = document.getElementById('searchInput');
    const filterPills = document.querySelectorAll('.filter-pill');
    const newsCards = document.querySelectorAll('.news-card');

    // Show more posts
    showMoreBtn.addEventListener('click', () => {
      const batch = morePosts.slice(loadedCount, loadedCount + 6);
      batch.forEach(post => {
        const card = document.createElement('article');
        card.className = 'news-card';
        card.dataset.category = post.category;
        card.innerHTML = `
          <span class="category-tag">${post.category}</span>
          <h3>${post.title}</h3>
          <p>${post.excerpt}</p>
          <div class="news-card-meta">
            <div class="author-avatar">${post.initials}</div>
            <span>${post.date} · ${post.author}</span>
          </div>
        `;
        newsGrid.appendChild(card);
      });
      loadedCount += batch.length;
      if (loadedCount >= morePosts.length) {
        showMoreBtn.style.display = 'none';
      }
    });

    // Category filtering
    function filterPosts() {
      const searchTerm = searchInput.value.toLowerCase();
      const activeCategory = document.querySelector('.filter-pill.active').dataset.category;

      let visibleCount = 0;

      newsCards.forEach(card => {
        const category = card.dataset.category;
        const title = card.querySelector('h3').textContent.toLowerCase();
        const excerpt = card.querySelector('p').textContent.toLowerCase();

        const matchesCategory = activeCategory === 'all' || category === activeCategory;
        const matchesSearch = !searchTerm || title.includes(searchTerm) || excerpt.includes(searchTerm);

        if (matchesCategory && matchesSearch) {
          card.style.display = 'block';
          visibleCount++;
        } else {
          card.style.display = 'none';
        }
      });

      // Also filter newly added posts
      const allCards = newsGrid.querySelectorAll('.news-card');
      allCards.forEach(card => {
        if (!newsCards.includes(card)) {
          const category = card.dataset.category;
          const title = card.querySelector('h3').textContent.toLowerCase();
          const excerpt = card.querySelector('p').textContent.toLowerCase();

          const matchesCategory = activeCategory === 'all' || category === activeCategory;
          const matchesSearch = !searchTerm || title.includes(searchTerm) || excerpt.includes(searchTerm);

          card.style.display = (matchesCategory && matchesSearch) ? 'block' : 'none';
        }
      });

      noResults.style.display = visibleCount === 0 ? 'block' : 'none';
      showMoreBtn.style.display = visibleCount === 0 ? 'none' : 'block';
    }

    filterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        filterPills.forEach(p => {
          p.classList.remove('active');
          p.setAttribute('aria-selected', 'false');
        });
        pill.classList.add('active');
        pill.setAttribute('aria-selected', 'true');
        filterPosts();
      });
    });

    searchInput.addEventListener('input', filterPosts);

    // Re-initialize icons for dynamically added content
    const observer = new MutationObserver(() => {
      lucide.createIcons();
    });
    observer.observe(newsGrid, { childList: true });
  </script>
